const j = $input.first().json;
const ctx = $('Validate Visual Contract + Untrusted Boundary').first().json;
const rawText = j.choices?.[0]?.message?.content || j.candidates?.[0]?.content?.parts?.[0]?.text || j.output_text || j.text || '';
if (!String(rawText).trim()) {
  throw new Error('EMPTY_VISION_ANALYSIS: No content returned by vision provider');
}
const inputTokens = j.usage?.prompt_tokens || j.usageMetadata?.promptTokenCount || null;
const outputTokens = j.usage?.completion_tokens || j.usageMetadata?.candidatesTokenCount || null;
const reqId = j.id || j.responseId || ('req_vis_' + crypto.randomUUID());

return [{
  json: {
    ...ctx,
    visual_text: String(rawText).trim(),
    provider_request_id: reqId,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    estimated_cost_usd: ctx.vision_provider === 'openai' ? 0.002 : 0.0005
  }
}];

const norm = $('Normalize Vision Output').first().json;
const sourceRes = $('Persist Visual Source Text').first().json.res;
const stId = sourceRes.source_text_id || (typeof sourceRes === 'string' ? JSON.parse(sourceRes).source_text_id : null);
const usageId = $('Record Visual AI Usage').first().json.id;

return [{
  json: {
    ok: true,
    status: 'completed',
    ingestion_id: norm.ingestion_id,
    asset_id: norm.asset_id,
    source_text_id: stId,
    visual_text: norm.visual_text,
    provider: norm.vision_provider,
    model: norm.vision_model,
    usage_id: usageId
  }
}];
